import { logger } from '../../logger'
import { fetchResultBody } from './poller'
import type { CicdInterpretedResult, PostProcessContext } from './types'

/**
 * `CicdOperation.postProcess` for `tests.run_test`/`tests.watch`. The sn_cicd progress tracker
 * (`ctx.progress.successful`) is the sole source of truth for pass/fail — it's always available
 * and doesn't depend on a second network call succeeding. This only fetches the linked
 * `sys_atf_test_result` record (`links.results.id`) to enrich the summary/displayMessage with
 * `test_status`/`output`; if there's no result id, or fetching it fails, that enrichment is
 * simply skipped rather than turning a tracker-successful run into a reported failure.
 */
export async function fetchAndInterpretTestResult(ctx: PostProcessContext): Promise<CicdInterpretedResult> {
    const successful = ctx.progress.successful
    const resultId = ctx.progress.links?.['results']?.id
    if (typeof resultId !== 'string') {
        return { successful, summary: { trackerId: ctx.progressId } }
    }

    let result: Record<string, unknown>
    try {
        const body = await fetchResultBody(ctx.connector, `api/sn_cicd/tests/test/results/${resultId}`)
        logger.debug(`ATF test result response for '${resultId}':`, JSON.stringify(body['result'] ?? body))
        result = (body['result'] as Record<string, unknown> | undefined) ?? {}
    } catch (error) {
        logger.debug(`Failed to fetch ATF test result '${resultId}' for extra detail:`, error)
        return { successful, summary: { trackerId: ctx.progressId, resultId } }
    }

    const links = result['links'] as Record<string, unknown> | undefined
    const results = links?.['results'] as Record<string, unknown> | undefined
    const resultUrl = typeof results?.['url'] === 'string' ? (results['url'] as string) : undefined
    const testStatus = result['test_status'] as string | undefined
    const output = result['output'] as string | undefined
    const displayMessage = [
        testStatus ? `Test result: ${testStatus}` : undefined,
        output,
        resultUrl ? `Details: ${resultUrl}` : undefined,
    ]
        .filter(Boolean)
        .join('\n')

    return {
        successful,
        summary: {
            trackerId: ctx.progressId,
            resultId,
            resultUrl,
            testStatus,
            output,
        },
        ...(displayMessage ? { displayMessage } : {}),
    }
}

/**
 * `CicdOperation.postProcess` for `testsuite.run`/`testsuite.watch`. Same policy as
 * `fetchAndInterpretTestResult`: the tracker's own `successful` decides pass/fail; the fetched
 * suite result (`links.results.id`) only adds richer status/counts/name/link when it's available,
 * and a missing link or failed fetch degrades to the tracker's outcome with no extra detail rather
 * than throwing.
 *
 * These are the REST wrapper's actual field names, confirmed against a live instance — NOT
 * `sys_atf_test_suite_result`'s GlideRecord field names. There's no `success` boolean and no plain
 * `success_count`/`failure_count`/etc.; only `rolledup_test_*_count` (spelled "rolledup", not
 * "rolled_up"). `links.results.url` mirrors the test-result shape (confirmed live).
 */
export async function fetchAndInterpretTestSuiteResult(ctx: PostProcessContext): Promise<CicdInterpretedResult> {
    const successful = ctx.progress.successful
    const resultId = ctx.progress.links?.['results']?.id
    if (typeof resultId !== 'string') {
        return { successful, summary: { trackerId: ctx.progressId } }
    }

    let result: Record<string, unknown>
    try {
        const body = await fetchResultBody(ctx.connector, `api/sn_cicd/testsuite/results/${resultId}`)
        logger.debug(`ATF test suite result response for '${resultId}':`, JSON.stringify(body['result'] ?? body))
        result = (body['result'] as Record<string, unknown> | undefined) ?? {}
    } catch (error) {
        logger.debug(`Failed to fetch ATF test suite result '${resultId}' for extra detail:`, error)
        return { successful, summary: { trackerId: ctx.progressId, resultId } }
    }

    const links = result['links'] as Record<string, unknown> | undefined
    const results = links?.['results'] as Record<string, unknown> | undefined
    const resultUrl = typeof results?.['url'] === 'string' ? (results['url'] as string) : undefined
    const testSuiteStatus = result['test_suite_status'] as string | undefined
    const successCount = result['rolledup_test_success_count']
    const failureCount = result['rolledup_test_failure_count']
    const errorCount = result['rolledup_test_error_count']
    const skipCount = result['rolledup_test_skip_count']
    const counts = `${successCount ?? 0} passed, ${failureCount ?? 0} failed, ${errorCount ?? 0} errored, ${skipCount ?? 0} skipped`

    return {
        successful,
        summary: {
            trackerId: ctx.progressId,
            resultId,
            resultUrl,
            testSuiteName: result['test_suite_name'],
            testSuiteStatus,
            successCount,
            failureCount,
            errorCount,
            skipCount,
        },
        displayMessage: [
            testSuiteStatus ? `Suite result: ${testSuiteStatus}` : undefined,
            counts,
            resultUrl ? `Details: ${resultUrl}` : undefined,
        ]
            .filter(Boolean)
            .join('\n'),
    }
}
